#include <bits/stdc++.h>
using namespace std;

int power_mod(int base, int exp, int mod) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * base % mod;
        base = (long long)base * base % mod;
        exp >>= 1;
    }
    return res;
}

const int MAX_SIZE = 300005;
unsigned long long dp_state[27][MAX_SIZE];
int fact[MAX_SIZE], inv_fact[MAX_SIZE];

int get_permutation(int n, int m, int mod) {
    return (long long)fact[n] * inv_fact[n - m] % mod;
}

int main() {
    int n, K, MOD;
    scanf("%d %d %d", &n, &K, &MOD);
    if (n % 2 != 0) {
        printf("%d\n", power_mod(K, n, MOD));
        return 0;
    }
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fact[i] = (long long)fact[i - 1] * i % MOD;
    }
    inv_fact[n] = power_mod(fact[n], MOD - 2, MOD);
    for (int i = n - 1; i >= 0; --i) {
        inv_fact[i] = (long long)inv_fact[i + 1] * (i + 1) % MOD;
    }
    dp_state[0][0] = 1ULL;
    for (int k = 0; k < K; ++k) {
        for (int i = 1; i <= n; ++i) {
            if ((i & n) != i) continue;
            int block_mask = 1 << (31 - __builtin_clz(i));
            unsigned long long &res = dp_state[k + 1][i];
            res = 0ULL;
            for (int j = i - block_mask; j >= 0; j = (j - 1) & i) {
                int j_plus = j + block_mask;
                res += dp_state[k][i ^ j_plus] * inv_fact[j_plus];
                if (++cnt == 17) {
                    res %= MOD;
                    cnt = 0;
                }
                if (j == 0) break;
            }
            res %= MOD;
        }
    }
    int total_result = 0;
    for (int i = 0; i <= K; ++i) {
        total_result = (total_result + (long long)fact[n] * dp_state[i][n] % MOD * get_permutation(K, i, MOD)) % MOD;
    }
    printf("%d\n", (power_mod(K, n, MOD) + MOD - total_result) % MOD);
}
